<template>
	<view class="gallery-manage" :class="{ night: night }">
		<view class="manage-nav" :style="{ paddingTop: StatusBar + 'px' }"><view class="manage-nav-inner"><text class="cuIcon-back" @tap="back"></text><text class="manage-nav-title">图集审核</text><text class="manage-nav-note">GALLERY</text></view></view>
		<view class="manage-content" :style="{ paddingTop: (StatusBar + 58) + 'px' }">
			<view class="intro"><view><text class="eyebrow">IMAGE CHANNEL</text><text class="intro-title">把校园照片，整理成册</text><text class="intro-desc">审核独立图集，不会混入动态、问答或普通帖子。</text></view><view class="intro-mark"><text class="cuIcon-picfill"></text></view></view>
			<view class="filters"><text v-for="item in statuses" :key="item.value" :class="{ active: status === item.value }" @tap="setStatus(item.value)">{{ item.label }}</text></view>
			<view class="tag-filter"><text class="cuIcon-search"></text><input v-model="tag" placeholder="按标签筛选" confirm-type="search" @confirm="reload" /><text v-if="tag" class="cuIcon-close" @tap="clearTag"></text></view>
			<view v-if="!loading && !items.length" class="empty"><text class="empty-mark">○</text><text>暂无图集</text><text class="empty-sub">新的投稿会出现在这里。</text></view>
			<view v-for="item in items" :key="item.id" class="gallery-row"><view class="gallery-images" @tap="preview(item)"><image v-if="item.imageUrls && item.imageUrls[0]" :src="item.imageUrls[0]" mode="aspectFill" /><view v-else class="image-fallback"><text class="cuIcon-picfill"></text></view><text v-if="item.imageUrls && item.imageUrls.length > 1" class="image-count">{{ item.imageUrls.length }} 张</text></view><view class="gallery-main"><view class="gallery-title-line"><text class="gallery-title">{{ item.title }}</text><text class="status" :class="'status-' + item.status">{{ statusLabel(item.status) }}</text></view><text v-if="item.description" class="gallery-description">{{ item.description }}</text><text class="gallery-meta">{{ item.authorName || '未知用户' }} · {{ formatDate(item.created) }} · {{ item.views || 0 }} 次浏览</text><view class="gallery-tags"><text v-for="tagName in item.tags || []" :key="tagName">#{{ tagName }}</text></view><text v-if="item.reviewReason" class="gallery-reason">审核意见：{{ item.reviewReason }}</text></view><view class="gallery-actions"><text @tap="preview(item)">查看</text><text v-if="item.status === 'submitted'" class="publish" @tap="review(item, 'published')">发布</text><text v-if="item.status === 'submitted'" class="reject" @tap="review(item, 'rejected')">退回</text><text v-if="item.status === 'published'" class="reject" @tap="review(item, 'hidden')">隐藏</text><text v-if="item.status === 'hidden' || item.status === 'rejected'" class="publish" @tap="review(item, 'published')">恢复发布</text><text v-if="item.status !== 'deleted'" class="delete" @tap="remove(item)">删除</text></view></view>
			<view v-if="items.length" class="load-more" @tap="loadMore">{{ moreText }}</view>
		</view>
		<view v-if="previewItem" class="preview-mask" @tap="previewItem = null"><view class="preview-sheet" @tap.stop><view class="preview-head"><text class="preview-title">{{ previewItem.title }}</text><text class="cuIcon-close" @tap="previewItem = null"></text></view><scroll-view scroll-y class="preview-scroll"><image v-for="url in previewItem.imageUrls || []" :key="url" :src="url" mode="widthFix" @tap="showImage(url)" /><text class="preview-description">{{ previewItem.description || '没有描述' }}</text></scroll-view></view></view>
		<view v-if="reasonEditor" class="reason-mask" @tap="reasonEditor = false"><view class="reason-sheet" @tap.stop><text class="reason-title">退回图集</text><textarea v-model="reason" maxlength="500" placeholder="填写退回理由，作者会看到这条意见" /><view class="reason-actions"><text @tap="reasonEditor = false">取消</text><text class="confirm" @tap="confirmReject">确认退回</text></view></view></view>
	</view>
</template>

<script>
import { localStorage } from '../../js_sdk/mp-storage/mp-storage/index.js'

export default {
	data() { return { StatusBar: this.StatusBar, token: '', group: '', night: false, status: 'submitted', tag: '', items: [], loading: false, page: 1, total: 0, moreText: '加载更多', previewItem: null, reasonEditor: false, reason: '', rejecting: null, statuses: [{ label: '待审核', value: 'submitted' }, { label: '已发布', value: 'published' }, { label: '已退回', value: 'rejected' }, { label: '已隐藏', value: 'hidden' }, { label: '已删除', value: 'deleted' }, { label: '全部', value: '' }] } },
	onLoad() { this.token = localStorage.getItem('token') || ''; try { const info = JSON.parse(localStorage.getItem('userinfo') || '{}'); this.group = info.group || ''; this.night = info.isNight === 1 } catch (e) {} if (this.group !== 'administrator' && this.group !== 'editor') { uni.showToast({ title: '没有管理权限', icon: 'none' }); return } this.reload() },
	methods: {
		back() { uni.navigateBack({ delta: 1 }) },
		reload() { this.page = 1; this.loadList(false) },
		setStatus(value) { if (this.status === value) return; this.status = value; this.reload() },
		clearTag() { this.tag = ''; this.reload() },
		loadMore() { if (this.loading || this.items.length >= this.total) return; this.loadList(true) },
		loadList(append) { if (this.loading) return; this.loading = true; const page = append ? this.page + 1 : 1; this.$Net.request({ url: this.$API.galleryManage(), data: { token: this.token, status: this.status, tag: this.tag.trim(), page, limit: 20 }, method: 'get', dataType: 'json', success: res => { if (res.data && res.data.code === 1) { const rows = Array.isArray(res.data.data) ? res.data.data : []; this.items = append ? this.items.concat(rows) : rows; this.page = page; this.total = Number(res.data.total || 0); this.moreText = this.items.length < this.total ? '加载更多' : '已经到底了' } else uni.showToast({ title: res.data && res.data.msg || '列表加载失败', icon: 'none' }) }, fail: () => uni.showToast({ title: '图集列表加载失败', icon: 'none' }), complete: () => { this.loading = false } }) },
		statusLabel(value) { return { submitted: '待审核', published: '已发布', rejected: '已退回', hidden: '已隐藏', deleted: '已删除' }[value] || '未知' },
		formatDate(value) { const date = new Date(Number(value) > 10000000000 ? Number(value) : Number(value) * 1000); return isNaN(date.getTime()) ? '' : date.getFullYear() + '.' + String(date.getMonth() + 1).padStart(2, '0') + '.' + String(date.getDate()).padStart(2, '0') },
		preview(item) { this.previewItem = item },
		showImage(url) { uni.previewImage({ urls: this.previewItem.imageUrls || [], current: url }) },
		review(item, next) { if (next === 'rejected') { this.rejecting = item; this.reason = ''; this.reasonEditor = true; return } const title = next === 'published' ? (item.status === 'hidden' || item.status === 'rejected' ? '恢复发布这组图？' : '发布这组图？') : '隐藏这组图？'; uni.showModal({ title, content: next === 'published' ? '公开后普通用户可以在图库中看到它。' : '隐藏后普通用户将无法看到它。', success: res => { if (res.confirm) this.submitReview(item, next, '') } }) },
		confirmReject() { if (!this.rejecting) return; const item = this.rejecting; this.reasonEditor = false; this.rejecting = null; this.submitReview(item, 'rejected', this.reason) },
		submitReview(item, next, reason) { uni.showLoading({ title: '处理中' }); this.$Net.request({ url: this.$API.galleryReview(), data: { token: this.token, id: item.id, status: next, reason: reason || '', _ts: Date.now() }, method: 'post', dataType: 'json', success: res => { uni.hideLoading(); uni.showToast({ title: res.data && res.data.msg || '已更新', icon: 'none' }); if (res.data && res.data.code === 1) this.reload() }, fail: () => { uni.hideLoading(); uni.showToast({ title: '网络不太好，请稍后重试', icon: 'none' }) } }) },
		remove(item) { uni.showModal({ title: '删除这组图？', content: '删除后会从公开图库移除，并保留审核审计记录。', confirmText: '删除', confirmColor: '#a04f45', success: res => { if (!res.confirm) return; uni.showLoading({ title: '删除中' }); this.$Net.request({ url: this.$API.galleryDelete(), data: { token: this.token, id: item.id, reason: '管理员删除', _ts: Date.now() }, method: 'post', dataType: 'json', success: response => { uni.hideLoading(); uni.showToast({ title: response.data && response.data.msg || '已删除', icon: 'none' }); if (response.data && response.data.code === 1) this.reload() }, fail: () => { uni.hideLoading(); uni.showToast({ title: '删除失败', icon: 'none' }) } }) } }) }
	}
}
</script>

<style scoped>
.gallery-manage{min-height:100vh;background:#f4f6f5;color:#263630}.manage-nav{position:fixed;left:0;right:0;top:0;z-index:5;background:rgba(255,255,255,.96);border-bottom:1px solid #e3eae6;backdrop-filter:blur(12px)}.manage-nav-inner{height:58px;display:flex;align-items:center;gap:16px;padding:0 22px}.manage-nav-inner>.cuIcon-back{font-size:20px;color:#4d7062}.manage-nav-title{font-size:20px;font-weight:650}.manage-nav-note{margin-left:auto;color:#94a49c;font-size:10px;letter-spacing:2px}.manage-content{max-width:980px;margin:auto;padding:0 22px 70px}.intro{display:flex;justify-content:space-between;align-items:flex-end;padding:34px 0 28px;border-bottom:1px solid #dbe5df}.eyebrow{display:block;color:#9b704f;font-size:10px;letter-spacing:2px}.intro-title{display:block;margin-top:12px;color:#295142;font-size:30px;font-weight:700}.intro-desc{display:block;margin-top:10px;color:#7c8d84;font-size:12px}.intro-mark{display:flex;align-items:center;justify-content:center;width:58px;height:58px;border-radius:16px;background:#2e6657;color:#fff;font-size:27px}.filters{display:flex;gap:20px;overflow-x:auto;padding:18px 0 12px;white-space:nowrap}.filters text{padding-bottom:8px;color:#809087;font-size:12px}.filters .active{color:#2e6657;border-bottom:2px solid #2e6657;font-weight:650}.tag-filter{display:flex;align-items:center;gap:8px;height:38px;margin-bottom:10px;padding:0 12px;border-radius:7px;background:#eaf0ec;color:#819189}.tag-filter input{min-width:0;flex:1;font-size:12px}.gallery-row{display:flex;align-items:center;gap:14px;padding:14px 0;border-bottom:1px solid #dbe5df}.gallery-images{position:relative;width:86px;height:86px;flex:none;overflow:hidden;border-radius:7px;background:#e3ebe6}.gallery-images image{width:100%;height:100%}.image-fallback{display:flex;align-items:center;justify-content:center;width:100%;height:100%;color:#8da199;font-size:27px}.image-count{position:absolute;right:5px;bottom:5px;padding:3px 6px;border-radius:10px;background:#15221dcc;color:#fff;font-size:10px}.gallery-main{min-width:0;flex:1}.gallery-title-line{display:flex;align-items:center;gap:8px}.gallery-title{overflow:hidden;color:#294d40;font-size:16px;font-weight:650;text-overflow:ellipsis;white-space:nowrap}.status{padding:3px 7px;border-radius:10px;flex:none;font-size:10px}.status-submitted{background:#f4e5d7;color:#9b6949}.status-published{background:#deece4;color:#3d765f}.status-rejected,.status-hidden,.status-deleted{background:#ecebe7;color:#8a918e}.gallery-description{display:-webkit-box;overflow:hidden;margin-top:7px;color:#6e7f76;font-size:12px;line-height:1.45;-webkit-box-orient:vertical;-webkit-line-clamp:2}.gallery-meta{display:block;margin-top:7px;color:#98a69e;font-size:10px}.gallery-tags{display:flex;gap:7px;overflow:hidden;margin-top:7px;color:#58806e;font-size:10px;white-space:nowrap}.gallery-reason{display:block;margin-top:6px;color:#a4664a;font-size:10px}.gallery-actions{display:flex;flex-direction:column;align-items:flex-end;gap:8px;flex:none;color:#56796c;font-size:12px}.gallery-actions .publish{color:#2e765c}.gallery-actions .reject,.gallery-actions .delete{color:#a4664a}.empty{text-align:center;padding:80px 20px;color:#6f8379}.empty-mark{display:block;color:#afc1b7;font:42px Georgia,serif}.empty-sub{display:block;margin-top:8px;color:#a0aaa4;font-size:12px}.load-more{text-align:center;padding:20px;color:#668277;font-size:12px}.preview-mask,.reason-mask{position:fixed;inset:0;z-index:20;background:#13221d66;display:flex;align-items:flex-end}.preview-sheet,.reason-sheet{width:100%;max-height:88vh;overflow:hidden;border-radius:20px 20px 0 0;background:#fafcf9}.preview-head{display:flex;align-items:center;justify-content:space-between;padding:20px 22px 14px}.preview-title,.reason-title{color:#294d40;font-size:19px;font-weight:650}.preview-scroll{height:calc(88vh - 68px);padding:0 22px 24px;box-sizing:border-box}.preview-scroll image{display:block;width:100%;margin-top:10px;border-radius:7px}.preview-description{display:block;padding:14px 0;color:#6d7f76;font-size:12px;line-height:1.6}.reason-sheet{padding:24px 22px 30px}.reason-sheet textarea{width:100%;height:110px;margin-top:18px;padding:11px;border:1px solid #d5dfd8;border-radius:7px;background:#fff;font-size:13px;box-sizing:border-box}.reason-actions{display:flex;justify-content:flex-end;gap:18px;margin-top:16px;color:#6c8076;font-size:13px}.reason-actions .confirm{color:#2e6657;font-weight:650}.night{background:#1e2522;color:#e6eee8}.night .manage-nav{background:rgba(30,37,34,.96);border-color:#39463f}.night .intro,.night .gallery-row{border-color:#39463f}.night .intro-title,.night .gallery-title,.night .preview-title,.night .reason-title{color:#e3eee7}.night .intro-desc,.night .gallery-description{color:#9eafa5}.night .tag-filter{background:#29322f}.night .preview-sheet,.night .reason-sheet{background:#202a26}@media(max-width:560px){.manage-content{padding-left:16px;padding-right:16px}.intro-title{font-size:25px}.intro-mark{width:50px;height:50px}.gallery-row{gap:10px}.gallery-images{width:72px;height:72px}.gallery-actions{gap:6px;font-size:11px}.gallery-title{font-size:14px}.manage-nav-inner{padding:0 16px}}
</style>
